#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/ATen.h>
#include <ATen/cuda/CUDAContext.h>

template <typename scalar_t>
__global__ void maxpool1d_forward_kernel(
    const scalar_t* __restrict__ input,
    scalar_t* __restrict__ output,
    const int batch,
    const int channels,
    const int in_len,
    const int out_len,
    const int kernel_size,
    const int stride,
    const int padding,
    const int dilation)
{
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total = batch * channels * out_len;
    if (idx >= total) return;

    const int out_pos = idx % out_len;
    const int chan = (idx / out_len) % channels;
    const int b = idx / (out_len * channels);

    const int input_base = b * channels * in_len + chan * in_len;

    const int start = out_pos * stride - padding;
    float max_val = -65504.0f; // lowest fp16 value

    #pragma unroll
    for (int k = 0; k < kernel_size; ++k) {
        const int in_idx = start + k * dilation;
        if (in_idx >= 0 && in_idx < in_len) {
            float val = static_cast<float>(input[input_base + in_idx]);
            if (val > max_val) max_val = val;
        }
    }
    output[idx] = static_cast<scalar_t>(max_val);
}

void maxpool1d_forward(
    torch::Tensor input,
    torch::Tensor output,
    const int kernel_size,
    const int stride,
    const int padding,
    const int dilation)
{
    const int batch   = input.size(0);
    const int channels= input.size(1);
    const int in_len  = input.size(2);
    const int out_len = output.size(2);

    const int threads = 256;
    const int total   = batch * channels * out_len;
    const int blocks  = (total + threads - 1) / threads;

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "maxpool1d_forward_kernel", ([&] {
        maxpool1d_forward_kernel<scalar_t><<<blocks, threads, 0, at::cuda::getCurrentCUDAStream()>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            batch,
            channels,
            in_len,
            out_len,
            kernel_size,
            stride,
            padding,
            dilation);
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA error in maxpool1d_forward: %s\\n", cudaGetErrorString(err));
    }
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("maxpool1d_forward", &maxpool1d_forward, "MaxPool1d forward (CUDA, fp16)");
}
'''

module = load_inline(name='maxpool1d_cuda',
                     cpp_sources='',
                     cuda_sources=src,
                     functions=['maxpool1d_forward'],
                     verbose=False)

class ModelNew(nn.Module):
    def __init__(self, kernel_size: int, stride: int = None, padding: int = 0,
                 dilation: int = 1, return_indices: bool = False):
        super().__init__()
        self.kernel_size = kernel_size
        self.stride = stride if stride is not None else kernel_size
        self.padding = padding
        self.dilation = dilation
        self.return_indices = return_indices
        if self.return_indices:
            raise NotImplementedError("return_indices=True is not supported in the custom kernel.")

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if x.dtype != torch.float16:
            x = x.half()
        x = x.contiguous()
        batch, channels, in_len = x.shape

        # compute output length using PyTorch's formula
        out_len = (in_len + 2 * self.padding -
                   self.dilation * (self.kernel_size - 1) - 1) // self.stride + 1

        out = torch.empty((batch, channels, out_len),
                          dtype=torch.float16,
                          device=x.device)

        module.maxpool1d_forward(x, out,
                                 self.kernel_size,
                                 self.stride,
                                 self.padding,
                                 self.dilation)
        return out
